const GROUPS = [
  { key: 'root',  label: 'Root · PR1-3',  color: '#2a78d6' },
  { key: 'leaf',  label: 'Leaf · PL1-3',  color: '#eb6834' },
  { key: 'stem',  label: '“Stem” · P1-3', color: '#1baf7a' },
]

// fraction of reads below 40 % GC, computed from the same curves
const LOWGC = { root: '15.1 – 16.4 %', leaf: '25.4 – 28.8 %', stem: '10.3 – 12.5 %' }

const W = 560, H = 250, ML = 38, MR = 104, MT = 10, MB = 28
const X0 = 18, X1 = 72, Y1 = 5.6
const sx = x => ML + (x - X0) / (X1 - X0) * (W - ML - MR)
const sy = y => H - MB - y / Y1 * (H - MT - MB)
const path = pts => pts.map((p, i) => (i ? 'L' : 'M') + sx(p[0]).toFixed(1) + ' ' + sy(p[1]).toFixed(1)).join(' ')

const hot = ref(null)
const dim = k => hot.value && hot.value !== k
