        <text :x="sx(t)" :y="H - MB + 13" class="tick">{{ t }}</text>
      </g>
      <g v-for="t in [0, 2, 4]" :key="'y' + t">
        <line :x1="ML - 3" :y1="sy(t)" :x2="W - MR" :y2="sy(t)" class="grid" />
        <text :x="ML - 6" :y="sy(t) + 3" class="tick" text-anchor="end">{{ t }}</text>
      </g>
      <text :x="(ML + W - MR) / 2" :y="H - 2" class="axlab">GC content of read (%)</text>
      <text class="axlab" :transform="`rotate(-90, 12, ${(MT + H - MB) / 2}) translate(12, ${(MT + H - MB) / 2})`" x="0" y="0">% of reads</text>

      <!-- one line per library, three per tissue -->
      <path v-for="(s, name) in SERIES" :key="name" :d="path(s.p)"
            :stroke="GROUPS.find(g => g.key === s.t).color"
            :style="{ opacity: dim(s.t) ? 0.18 : 0.9 }"
            fill="none" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round" />

      <!-- direct labels -->
      <g v-for="(g, i) in GROUPS" :key="g.key"
         @mouseenter="hot = g.key" @mouseleave="hot = null" class="lg">
        <rect :x="W - MR + 2" :y="MT + 6 + i * 40" width="98" height="34" rx="4"
              :fill="g.color" :style="{ opacity: dim(g.key) ? 0.05 : 0.13 }" />
        <text :x="W - MR + 8" :y="MT + 19 + i * 40" class="lglab" :fill="g.color">{{ g.label }}</text>
        <text :x="W - MR + 8" :y="MT + 31 + i * 40" class="lgsub">&lt;40 % GC: {{ LOWGC[g.key] }}</text>
      </g>
    </svg>

  </div>
</template>

